package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Term    string `json:"term"`
	Filters map[string]string `json:"filters"`
	OrderBy string `json:"order_by"`
	Limit   int    `json:"limit"`
}

type Document struct {
	ID      int    `json:"id"`
	Title   string `json:"title"`
	Content string `json:"content"`
	Owner   string `json:"owner"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func buildSearchQuery(req SearchRequest, userTenant string) string {
	// Base query with tenant isolation
	query := fmt.Sprintf("SELECT id, title, content, owner FROM documents WHERE tenant_id = '%s'", userTenant)

	// Add search term - uses ts_vector for full text search
	if req.Term != "" {
		// Sanitize by removing obvious dangerous patterns
		term := strings.ReplaceAll(req.Term, ";", "")
		term = strings.ReplaceAll(term, "--", "")
		query += fmt.Sprintf(" AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', '%s')", term)
	}

	// Apply filters
	for key, value := range req.Filters {
		switch key {
		case "owner":
			query += fmt.Sprintf(" AND owner = '%s'", value)
		case "created_after":
			query += fmt.Sprintf(" AND created_at > '%s'", value)
		case "tag":
			query += fmt.Sprintf(" AND tags @> ARRAY['%s']", value)
		}
	}

	// Order by - validate against allowlist
	allowedOrders := map[string]bool{"title": true, "created_at": true, "relevance": true}
	if allowedOrders[req.OrderBy] {
		if req.OrderBy == "relevance" {
			query += " ORDER BY ts_rank(to_tsvector('english', title || ' ' || content), plainto_tsquery('english', '" + req.Term + "')) DESC"
		} else {
			query += fmt.Sprintf(" ORDER BY %s", req.OrderBy)
		}
	}

	if req.Limit > 0 && req.Limit <= 100 {
		query += fmt.Sprintf(" LIMIT %d", req.Limit)
	} else {
		query += " LIMIT 20"
	}

	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Extract tenant from X-Tenant-ID header (set by upstream auth proxy)
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	query := buildSearchQuery(req, tenantID)
	log.Printf("Executing query for tenant %s: %s", tenantID, query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.Owner); err != nil {
			continue
		}
		docs = append(docs, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting document search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
